import type { ProviderAuthDescriptor } from '../../core/provider-port';

/**
 * LobbyPMS authenticates every call with one **per-property API token**, generated by an
 * ADMINISTRATOR user in the property's account (Configuraciones › Usuarios, Permisos y API › Acceso
 * API › Ver API Token). The documentation names it `api_token` on every method; this descriptor
 * places it in the query string, which is how the docs present it for GET and which the provider's
 * request parsing also reads for the JSON-body methods (Documented, 2026-10-15 — to be confirmed
 * with the first live call; `docs/design/lobbypms-provider/design-notes.md` › Q1).
 *
 * The docs' payment-link section also mentions a Bearer token. If the first live call shows that
 * `Authorization: Bearer` works on every method, switch to `bearer` and the credential leaves the
 * URL — that is the better placement, not taken now only because it is not documented for all.
 *
 * ⚠️ The credential travels **in the URL** (as with Toteat): a request URL is a credential, so it is
 * never placed in a tool result, an error message or a log — the containment tests pin it.
 *
 * `forwarded`, like Cloudbeds — a booking PMS, not a payments or fiscal provider. Payment links are
 * created in the property's own payment system; this server never moves money.
 *
 * Beyond the token, LobbyPMS also requires the CALLER'S PUBLIC IP to be authorized in the property:
 * this server's dedicated egress IPs (`.do/app.yaml` › `egress`).
 */
export const lobbypmsAuth: ProviderAuthDescriptor = {
  type: 'api_key',
  credentialDelivery: 'forwarded',
  fields: [{ key: 'api_token', label: 'API Token', placement: 'query' }],
};
